// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/nosql.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Fundamentos NoSQL", "t": "Qué es NoSQL", "x": "Bases de datos que no guardan los datos en tablas relacionales.\n\nNoSQL significa «no solo SQL». En lugar de tablas con columnas fijas usan documentos, pares clave-valor, columnas anchas o grafos. Escalan repartiendo datos entre muchos servidores. No reemplazan a SQL: cada una sirve para casos distintos.", "u": "Guardar datos flexibles, enormes o muy rápidos de leer.\n\nTu app guarda publicaciones con campos distintos cada una (texto, fotos, encuestas) y millones de lecturas.", "p": ["NoSQL significa no solo SQL.", "Las bases NoSQL no usan tablas relacionales.", "NoSQL no reemplaza a SQL en todos los casos."], "c": "// Un documento de MongoDB\n{ \"_id\": 1, \"usuario\": \"ana\", \"tipo\": \"foto\", \"likes\": 42, \"etiquetas\": [\"viaje\", \"mar\"] }", "h": "Un documento con campos propios.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las bases de datos que no usan tablas relacionales se llaman ___. (5 letras)", "e": "Usar NoSQL solo porque está de moda."},
  {"m": "Fundamentos NoSQL", "t": "Tipos de bases NoSQL", "x": "Las cuatro familias: documentos, clave-valor, columnas anchas y grafos.\n\nDocumentos (MongoDB, Firestore) guardan JSON; clave-valor (Redis, DynamoDB) son diccionarios ultrarrápidos; columnas anchas (Cassandra) manejan datos enormes; grafos (Neo4j) guardan relaciones como amistades o rutas.", "u": "Elegir la base correcta según los datos.\n\nDebes guardar quién sigue a quién en una red social y buscar «amigos de mis amigos» muy rápido.", "p": ["MongoDB es una base de documentos.", "Redis es una base de clave-valor.", "Neo4j es una base de grafos."], "c": "// clave-valor (Redis):  sesion:ana -> \"token123\"\n// grafo (Neo4j):       (Ana)-[:SIGUE]->(Luis)", "h": "Ejemplos de clave-valor y de grafo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de base NoSQL de MongoDB es de ___. (10 letras)", "e": "Usar una base de documentos para relaciones muy conectadas."},
  {"m": "Fundamentos NoSQL", "t": "JSON y BSON", "x": "Formatos de los documentos: JSON en texto y BSON en binario.\n\nLos documentos se escriben como JSON. MongoDB los guarda en BSON (JSON binario), que agrega tipos como Date, ObjectId, Decimal128 y binarios. Cada documento tiene un _id único.", "u": "Guardar objetos con tipos como fechas y números exactos.\n\nNecesitas guardar una fecha real (no texto) dentro de un documento de MongoDB.", "p": ["MongoDB guarda los documentos en BSON.", "BSON agrega tipos como Date y ObjectId.", "Cada documento de MongoDB tiene un _id."], "c": "db.pedidos.insertOne({ total: NumberDecimal(\"19.99\"), fecha: new Date() })", "h": "Guarda un precio exacto y una fecha real.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El formato binario de MongoDB es ___. (4 letras)", "e": "Guardar fechas como texto y no poder ordenarlas."},
  {"m": "Fundamentos NoSQL", "t": "Esquema flexible", "x": "Documentos de una misma colección pueden tener campos distintos.\n\nEn MongoDB no hay CREATE TABLE: agregas un campo nuevo y listo. Esa libertad exige orden: define una estructura en tu código (Mongoose, Pydantic) o con validación de esquema para no tener datos inconsistentes.", "u": "Cambiar la estructura sin migraciones largas.\n\nTus productos cambian seguido: unos tienen talla, otros voltaje y otros sabor.", "p": ["En MongoDB no se declara la tabla antes de insertar.", "Los documentos de una colección pueden tener campos distintos.", "La flexibilidad exige validar los datos."], "c": "db.productos.insertMany([{ nombre: \"Camisa\", talla: \"M\" }, { nombre: \"Licuadora\", voltaje: 110 }])", "h": "Dos productos con campos distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La característica de documentos con campos distintos es el esquema ___. (8 letras)", "e": "Guardar cada documento con nombres de campo distintos para lo mismo."},
  {"m": "Fundamentos NoSQL", "t": "Teorema CAP", "x": "Un sistema distribuido solo garantiza dos de tres: consistencia, disponibilidad y tolerancia a particiones.\n\nComo la red siempre puede fallar (P), hay que elegir: consistencia (C, todos ven el último dato) o disponibilidad (A, siempre responde aunque sea con un dato viejo). MongoDB tiende a CP y Cassandra a AP.", "u": "Entender las decisiones de diseño de cada base distribuida.\n\nTu base está repartida en dos países y se corta la conexión entre ellos.", "p": ["CAP significa consistencia, disponibilidad y tolerancia a particiones.", "Un sistema distribuido elige entre consistencia y disponibilidad.", "Cassandra prioriza la disponibilidad."], "c": "// C: todos ven el mismo dato\n// A: siempre responde\n// P: sigue funcionando si se corta la red", "h": "Las tres letras del teorema.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El teorema de consistencia, disponibilidad y particiones es el teorema ___. (3 letras)", "e": "Creer que una base distribuida puede tener las tres siempre."},
  {"m": "Fundamentos NoSQL", "t": "BASE y consistencia eventual", "x": "Modelo NoSQL donde los datos quedan iguales en todas las copias un poco después.\n\nBASE (Basically Available, Soft state, Eventually consistent) contrasta con ACID de SQL. Un «me gusta» puede tardar un segundo en verse en otro servidor, y está bien. Para dinero o inventario se pide consistencia fuerte o transacciones.", "u": "Tener sistemas muy disponibles aceptando pequeños retrasos.\n\nEn tu red social, un «me gusta» tarda un segundo en verse para otros usuarios y nadie se queja.", "p": ["BASE se opone al modelo ACID.", "Con consistencia eventual las copias se igualan después.", "Para pagos se prefiere consistencia fuerte."], "c": "// servidor A: likes = 42\n// servidor B: likes = 41  (en 1 segundo será 42)", "h": "Dos copias que se igualan poco después.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La consistencia en que las copias se igualan después es ___. (8 letras)", "e": "Usar consistencia eventual para saldos bancarios."},
  {"m": "Fundamentos NoSQL", "t": "Escalado horizontal", "x": "Agregar más servidores en lugar de uno más grande.\n\nEscalar vertical es comprar un servidor más potente; horizontal es repartir datos y carga entre muchos (sharding). Las bases NoSQL nacieron para escalar horizontalmente en la nube.", "u": "Atender más usuarios y datos sin un límite fijo.\n\nTu servidor de base de datos ya es el más grande que existe y aún no da abasto.", "p": ["Escalar horizontal es agregar más servidores.", "Escalar vertical es usar un servidor más potente.", "Las bases NoSQL escalan bien horizontalmente."], "c": "// vertical:   1 servidor de 64 núcleos\n// horizontal: 8 servidores de 8 núcleos", "h": "Comparación de los dos escalados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Agregar más servidores es escalar en forma ___. (10 letras)", "e": "Repartir datos entre servidores sin necesitarlo."},
  {"m": "Fundamentos NoSQL", "t": "SQL o NoSQL", "x": "Criterios para elegir entre una base relacional y una NoSQL.\n\nElige SQL si tus datos son muy relacionados, necesitas transacciones y consultas complejas (facturas, inventario). Elige NoSQL si la estructura cambia, necesitas escalar mucho o el acceso es por clave (catálogos, sesiones, chats, IoT). Muchos proyectos usan ambas.", "u": "Tomar la decisión correcta al empezar un proyecto.\n\nVas a programar el sistema de facturación con productos, clientes y pagos que deben cuadrar siempre.", "p": ["SQL conviene para datos muy relacionados.", "NoSQL conviene si la estructura cambia mucho.", "Muchos proyectos usan SQL y NoSQL a la vez."], "c": "// facturación → MySQL / PostgreSQL\n// sesiones y caché → Redis\n// catálogo flexible → MongoDB", "h": "Qué base usar para cada parte.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para facturas con transacciones conviene una base ___. (3 letras)", "e": "Elegir la base por moda y no por los datos."},
  {"m": "MongoDB esencial", "t": "MongoDB y Atlas", "x": "La base de documentos más usada y su servicio en la nube.\n\nMongoDB se instala en local (MongoDB Community) o se usa en Atlas, que da un clúster gratis (M0). Atlas entrega una cadena mongodb+srv://… y hay que permitir tu IP en Network Access. Compass es su programa gráfico.", "u": "Tener MongoDB sin instalar un servidor.\n\nQuieres usar MongoDB en tu proyecto del SENA sin instalar nada en el computador.", "p": ["Atlas es MongoDB en la nube.", "Atlas tiene un clúster gratis M0.", "Compass es el programa gráfico de MongoDB."], "c": "mongosh \"mongodb+srv://ana:CLAVE@cluster0.abcd.mongodb.net/tienda\"", "h": "Se conecta a un clúster de Atlas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El servicio de MongoDB en la nube es ___. (5 letras)", "e": "Olvidar permitir tu IP en Network Access."},
  {"m": "MongoDB esencial", "t": "mongosh", "x": "La terminal de MongoDB.\n\nmongosh abre la consola. show dbs lista bases, use tienda cambia (y crea al insertar), show collections lista colecciones y db.productos.find() consulta. Acepta JavaScript.", "u": "Consultar y administrar bases MongoDB con órdenes.\n\nQuieres ver desde la terminal qué bases de datos hay en tu servidor de MongoDB.", "p": ["mongosh es la terminal de MongoDB.", "use cambia de base de datos.", "show collections lista las colecciones."], "c": "show dbs\nuse tienda\nshow collections", "h": "Lista bases, cambia y lista colecciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La terminal de MongoDB se llama ___. (7 letras)", "e": "Creer que use crea la base aunque no insertes nada."},
  {"m": "MongoDB esencial", "t": "Bases y colecciones", "x": "Una base agrupa colecciones y una colección agrupa documentos.\n\nBase de datos ≈ base, colección ≈ tabla, documento ≈ fila y campo ≈ columna. Las colecciones se crean solas al insertar el primer documento. Se nombran en plural y minúsculas: usuarios, pedidos.", "u": "Organizar los datos como tablas y filas en SQL.\n\nEn SQL tendrías una tabla clientes.", "p": ["Una colección agrupa documentos.", "Una colección se parece a una tabla de SQL.", "La colección se crea al insertar el primer documento."], "c": "db.clientes.insertOne({ nombre: \"Ana\" })\ndb.getCollectionNames()", "h": "Crea la colección al insertar y la lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En MongoDB, el equivalente de una tabla es una ___. (9 letras)", "e": "Crear una colección por cada usuario."},
  {"m": "MongoDB esencial", "t": "insertOne e insertMany", "x": "Métodos para agregar uno o varios documentos.\n\ninsertOne(doc) agrega uno y devuelve su insertedId; insertMany([…]) agrega varios en una sola operación. Si no pones _id, MongoDB genera un ObjectId.", "u": "Guardar datos nuevos en una colección.\n\nDebes cargar 500 productos a la colección de una sola vez.", "p": ["insertOne agrega un documento.", "insertMany agrega varios documentos de una vez.", "MongoDB genera un ObjectId si no das _id."], "c": "db.productos.insertMany([\n  { nombre: \"Pan\", precio: 2 },\n  { nombre: \"Leche\", precio: 3 }\n])", "h": "Inserta dos productos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que agrega varios documentos es insert___. (4 letras)", "e": "Insertar en un bucle uno por uno miles de documentos."},
  {"m": "MongoDB esencial", "t": "find y filtros", "x": "Método que busca documentos que cumplen un filtro.\n\nfind({}) trae todos; find({ categoria: \"frutas\" }) filtra por igualdad y findOne trae el primero. Los filtros con varios campos son AND. find devuelve un cursor que mongosh muestra de a 20.", "u": "Leer solo los datos que necesitas.\n\nNecesitas todos los productos de la categoría «frutas».", "p": ["find busca documentos con un filtro.", "findOne devuelve el primer documento.", "Varios campos en el filtro se combinan con AND."], "c": "db.productos.find({ categoria: \"frutas\", activo: true })", "h": "Busca las frutas activas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que trae el primer documento que cumple el filtro es find___. (3 letras)", "e": "Traer toda la colección y filtrar en el código."},
  {"m": "MongoDB esencial", "t": "Operadores de consulta", "x": "Operadores con $ para comparar dentro de un filtro.\n\n$gt y $lt (mayor y menor), $gte y $lte, $ne (distinto), $in (en una lista), $or y $and combinan condiciones y $regex busca texto. Ejemplo: { precio: { $gte: 10, $lte: 50 } }.", "u": "Buscar por rangos, listas o condiciones.\n\nDebes listar los productos con precio entre 10 y 50.", "p": ["$gt significa mayor que.", "$in busca valores dentro de una lista.", "$or combina condiciones alternativas."], "c": "db.productos.find({ precio: { $gte: 10, $lte: 50 } })\ndb.productos.find({ categoria: { $in: [\"frutas\", \"lácteos\"] } })", "h": "Filtra por rango y por lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de MongoDB para «mayor que» es $___. (2 letras)", "e": "Olvidar el signo $ y buscar un campo llamado gt."},
  {"m": "MongoDB esencial", "t": "Proyección", "x": "Elegir qué campos devuelve una consulta.\n\nEl segundo argumento de find dice qué campos incluir (1) o excluir (0): find({}, { nombre: 1, precio: 1, _id: 0 }). No se mezclan inclusiones y exclusiones, salvo _id.", "u": "Traer solo lo necesario y ahorrar ancho de banda.\n\nTu lista de productos solo necesita nombre y precio, pero cada documento trae 40 campos.", "p": ["La proyección elige qué campos devuelve find.", "Con 1 se incluye un campo en la proyección.", "_id se puede excluir con 0."], "c": "db.productos.find({}, { nombre: 1, precio: 1, _id: 0 })", "h": "Devuelve solo nombre y precio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Elegir qué campos devuelve una consulta se llama ___. (10 letras)", "e": "Mezclar 1 y 0 en la misma proyección."},
  {"m": "MongoDB esencial", "t": "updateOne y $set", "x": "Métodos para modificar documentos.\n\nupdateOne(filtro, { $set: { precio: 5 } }) cambia un campo; $inc suma, $unset quita un campo y updateMany cambia varios. Sin $set reemplazarías todo el documento. { upsert: true } inserta si no existe.", "u": "Cambiar campos sin reemplazar el documento entero.\n\nDebes subir en 10 el stock de un producto sin tocar sus demás campos.", "p": ["$set cambia el valor de un campo.", "$inc suma una cantidad a un campo.", "upsert inserta el documento si no existe."], "c": "db.productos.updateOne({ nombre: \"Pan\" }, { $inc: { stock: 10 }, $set: { activo: true } })", "h": "Suma stock y activa el producto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que suma una cantidad es $___. (3 letras)", "e": "Olvidar $set y reemplazar todo el documento."},
  {"m": "MongoDB esencial", "t": "deleteOne, sort y limit", "x": "Borrar documentos y ordenar o limitar resultados.\n\ndeleteOne y deleteMany borran con un filtro (deleteMany({}) borra todo: cuidado). sort({ precio: -1 }) ordena de mayor a menor, limit(10) trae diez y skip(20) salta veinte para paginar.", "u": "Limpiar datos y mostrar listas paginadas.\n\nDebes mostrar los 5 productos más caros.", "p": ["deleteMany borra todos los documentos que cumplen el filtro.", "sort con -1 ordena de mayor a menor.", "skip y limit sirven para paginar."], "c": "db.productos.find().sort({ precio: -1 }).limit(5)", "h": "Los cinco productos más caros.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para ordenar de mayor a menor en sort se usa ___. (2 caracteres)", "e": "Ejecutar deleteMany({}) creyendo que borra solo uno."},
  {"m": "MongoDB avanzado", "t": "Documentos embebidos", "x": "Guardar un documento dentro de otro.\n\nUn pedido puede llevar dentro la dirección y sus productos. Así se lee todo de una vez, sin JOIN. Se embebe lo que se consulta junto y no crece sin límite (un documento tiene máximo 16 MB). Se consulta con punto: \"direccion.ciudad\".", "u": "Leer datos que siempre van juntos en una sola consulta.\n\nCada pedido siempre se muestra con su dirección de envío.", "p": ["Embeber guarda un documento dentro de otro.", "Los campos embebidos se consultan con punto.", "Un documento de MongoDB tiene máximo 16 MB."], "c": "db.pedidos.find({ \"direccion.ciudad\": \"Bogotá\" })", "h": "Busca pedidos por un campo embebido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Guardar un documento dentro de otro se llama ___. (7 letras)", "e": "Embeber listas que crecen sin límite, como todos los comentarios."},
  {"m": "MongoDB avanzado", "t": "Arrays en documentos", "x": "Listas de valores o documentos dentro de un campo.\n\n$push agrega a la lista, $pull quita y $addToSet agrega sin repetir. find({ etiquetas: \"oferta\" }) busca dentro del arreglo y $elemMatch filtra elementos que cumplen varias condiciones.", "u": "Guardar etiquetas, productos de un pedido o fotos.\n\nQuieres agregar la etiqueta «oferta» a un producto sin duplicarla si ya la tiene.", "p": ["$push agrega un elemento a un arreglo.", "$addToSet agrega sin repetir.", "$elemMatch filtra elementos de un arreglo."], "c": "db.productos.updateOne({ nombre: \"Pan\" }, { $addToSet: { etiquetas: \"oferta\" } })", "h": "Agrega una etiqueta sin repetir.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que agrega a un arreglo es $___. (4 letras)", "e": "Usar $push y llenar el arreglo de duplicados."},
  {"m": "MongoDB avanzado", "t": "Referencias y $lookup", "x": "Guardar el _id de otro documento y unirlos al consultar.\n\nUn pedido guarda clienteId en lugar de copiar al cliente. Al consultar, la etapa $lookup de la agregación une las colecciones, parecido a un LEFT JOIN. Se referencia lo que se comparte o crece mucho.", "u": "Relacionar colecciones cuando los datos crecen o se comparten.\n\nMuchos pedidos son del mismo cliente y sus datos cambian. Quieres ver cada pedido con el nombre del cliente.", "p": ["Una referencia guarda el _id de otro documento.", "$lookup une dos colecciones.", "$lookup se parece a un LEFT JOIN."], "c": "db.pedidos.aggregate([\n  { $lookup: { from: \"clientes\", localField: \"clienteId\", foreignField: \"_id\", as: \"cliente\" } }\n])", "h": "Une cada pedido con su cliente.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que une colecciones es $___. (6 letras)", "e": "Copiar los datos del cliente en cada pedido y no poder actualizarlos."},
  {"m": "MongoDB avanzado", "t": "Pipeline de agregación", "x": "Serie de etapas que transforman los documentos paso a paso.\n\naggregate([…]) recibe etapas en orden: $match filtra, $project elige campos, $sort ordena, $limit limita y $unwind separa arreglos. Cada etapa recibe la salida de la anterior.", "u": "Hacer reportes, totales y transformaciones en la base.\n\nNecesitas un reporte con los pedidos de noviembre, ordenados por total y solo con dos campos.", "p": ["aggregate recibe una lista de etapas.", "$match filtra documentos en la agregación.", "$unwind separa los elementos de un arreglo."], "c": "db.pedidos.aggregate([\n  { $match: { estado: \"pagado\" } },\n  { $sort: { total: -1 } },\n  { $project: { _id: 0, cliente: 1, total: 1 } }\n])", "h": "Pedidos pagados ordenados por total.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que filtra en una agregación es $___. (5 letras)", "e": "Poner $match al final y procesar documentos de más."},
  {"m": "MongoDB avanzado", "t": "$group", "x": "Etapa que agrupa documentos y calcula totales.\n\n{ $group: { _id: \"$categoria\", total: { $sum: \"$precio\" }, cantidad: { $sum: 1 } } } es como GROUP BY. También existen $avg, $min, $max y $push. Los campos se nombran con $ delante.", "u": "Sumar ventas por categoría, contar usuarios por ciudad.\n\nQuieres saber cuánto se vendió por cada categoría de producto.", "p": ["$group es como GROUP BY de SQL.", "$sum suma valores dentro de $group.", "En $group los campos se escriben con $ delante."], "c": "db.ventas.aggregate([{ $group: { _id: \"$categoria\", total: { $sum: \"$monto\" } } }])", "h": "Suma las ventas por categoría.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que agrupa documentos es $___. (5 letras)", "e": "Olvidar el $ delante del nombre del campo."},
  {"m": "MongoDB avanzado", "t": "Índices en MongoDB", "x": "Estructuras que aceleran las búsquedas por un campo.\n\ncreateIndex({ email: 1 }, { unique: true }) acelera y evita correos repetidos. explain(\"executionStats\") muestra si se usó el índice (IXSCAN) o se recorrió todo (COLLSCAN). Los índices hacen más lentas las escrituras: crea los necesarios.", "u": "Que las consultas no revisen toda la colección.\n\nBuscar usuarios por email tarda segundos porque la colección tiene millones de documentos.", "p": ["createIndex crea un índice.", "unique evita valores repetidos en un campo.", "COLLSCAN significa que se recorrió toda la colección."], "c": "db.usuarios.createIndex({ email: 1 }, { unique: true })", "h": "Crea un índice único por email.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que crea un índice es create___. (5 letras)", "e": "Crear índices en todos los campos."},
  {"m": "MongoDB avanzado", "t": "Validación de esquema", "x": "Reglas que MongoDB revisa antes de guardar un documento.\n\nAl crear la colección con validator y $jsonSchema defines campos obligatorios (required) y tipos (bsonType). Si un documento no cumple, la inserción falla. Combina flexibilidad con seguridad.", "u": "Evitar datos incompletos o con tipos equivocados.\n\nSe están guardando usuarios sin email y con la edad como texto.", "p": ["$jsonSchema define reglas de validación.", "required lista los campos obligatorios.", "bsonType indica el tipo esperado de un campo."], "c": "db.createCollection(\"usuarios\", { validator: { $jsonSchema: {\n  required: [\"email\"], properties: { edad: { bsonType: \"int\", minimum: 0 } } } } })", "h": "Exige email y edad entera.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador de validación de MongoDB es $json___. (6 letras)", "e": "Confiar en que la app siempre envía datos correctos."},
  {"m": "MongoDB avanzado", "t": "Mongoose y PyMongo", "x": "Librerías para usar MongoDB desde Node y Python.\n\nMongoose (Node) define esquemas y modelos: Producto.find(). PyMongo (Python) usa MongoClient y colecciones como diccionarios; Motor es su versión async para FastAPI. La cadena de conexión va en una variable de entorno.", "u": "Conectar tu backend a MongoDB.\n\nTu API de FastAPI debe guardar datos en MongoDB Atlas.", "p": ["Mongoose conecta Node con MongoDB.", "PyMongo conecta Python con MongoDB.", "La cadena de conexión va en una variable de entorno."], "c": "from pymongo import MongoClient\ncliente = MongoClient(\"mongodb://localhost:27017\")\nprint(cliente.tienda.productos.count_documents({}))", "h": "Cuenta los productos desde Python.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La librería de Python para MongoDB es ___. (7 letras)", "e": "Escribir la contraseña de Atlas en el código."},
  {"m": "Redis", "t": "Qué es Redis", "x": "Base de datos clave-valor en memoria, muy rápida.\n\nRedis guarda todo en RAM, por eso responde en menos de un milisegundo. Puede guardar a disco (RDB o AOF). Su terminal es redis-cli y su puerto por defecto es 6379. Valkey es una alternativa libre compatible.", "u": "Caché, sesiones, contadores y colas.\n\nTu página de inicio consulta la base de datos en cada visita y tarda; quieres guardar el resultado en memoria unos minutos.", "p": ["Redis guarda los datos en memoria.", "redis-cli es la terminal de Redis.", "El puerto por defecto de Redis es 6379."], "c": "redis-cli PING", "h": "Comprueba que Redis responde.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La terminal de Redis es redis-___. (3 letras)", "e": "Usar Redis como única copia de datos importantes."},
  {"m": "Redis", "t": "SET y GET", "x": "Órdenes básicas de Redis para guardar y leer un valor.\n\nSET clave valor guarda y GET clave lee. DEL borra, EXISTS pregunta si existe e INCR suma 1 de forma atómica (ideal para contadores de visitas). Las claves se nombran con dos puntos: usuario:7:nombre.", "u": "Guardar y recuperar datos por su clave.\n\nNecesitas contar las visitas de una página aunque lleguen miles al mismo tiempo.", "p": ["SET guarda un valor con su clave.", "GET lee el valor de una clave.", "INCR suma 1 de forma atómica."], "c": "SET usuario:7:nombre \"Ana\"\nGET usuario:7:nombre\nINCR visitas", "h": "Guarda, lee y cuenta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden de Redis que suma 1 de forma atómica es ___. (4 letras)", "e": "Leer, sumar en el código y guardar, y perder visitas."},
  {"m": "Redis", "t": "Expiración y TTL", "x": "Tiempo de vida de una clave antes de borrarse sola.\n\nSET codigo 123456 EX 300 guarda por 5 minutos; EXPIRE clave 60 pone un límite a una clave existente y TTL dice cuántos segundos le quedan (-1 si no expira, -2 si ya no existe).", "u": "Caché y códigos temporales que caducan.\n\nEl código de verificación que envías por correo debe dejar de servir a los 10 minutos.", "p": ["EX define en segundos cuánto vive una clave.", "TTL dice cuántos segundos le quedan a una clave.", "Una clave con expiración se borra sola."], "c": "SET verif:ana 482913 EX 600\nTTL verif:ana", "h": "Guarda un código por 10 minutos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que dice cuánto le queda a una clave es ___. (3 letras)", "e": "Guardar cachés sin expiración y llenar la memoria."},
  {"m": "Redis", "t": "Listas en Redis", "x": "Secuencias ordenadas de valores.\n\nLPUSH agrega al inicio y RPUSH al final; LPOP y RPOP sacan; LRANGE clave 0 9 lee los primeros diez y LTRIM recorta. Con BRPOP un trabajador espera tareas nuevas.", "u": "Colas de tareas y últimos elementos (últimas notificaciones).\n\nQuieres guardar las últimas 10 notificaciones de cada usuario y descartar las viejas.", "p": ["LPUSH agrega al inicio de una lista.", "LRANGE lee un rango de una lista.", "Las listas de Redis sirven como colas."], "c": "LPUSH notif:7 \"Nuevo mensaje\"\nLTRIM notif:7 0 9\nLRANGE notif:7 0 -1", "h": "Agrega una notificación y deja solo diez.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que lee un rango de una lista es ___. (6 letras)", "e": "Dejar crecer listas sin límite."},
  {"m": "Redis", "t": "Hashes en Redis", "x": "Objetos con varios campos bajo una sola clave.\n\nHSET usuario:7 nombre Ana ciudad Bogotá guarda campos; HGET lee uno, HGETALL todos y HINCRBY suma a un campo. Es más ordenado que una clave por campo.", "u": "Guardar el perfil de un usuario o un carrito.\n\nDebes guardar el carrito de compras con la cantidad de cada producto bajo una sola clave.", "p": ["Un hash guarda varios campos bajo una clave.", "HGETALL devuelve todos los campos de un hash.", "HINCRBY suma a un campo de un hash."], "c": "HSET carrito:7 pan 2 leche 1\nHINCRBY carrito:7 pan 1\nHGETALL carrito:7", "h": "Carrito con cantidades por producto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que devuelve todos los campos de un hash es ___. (7 letras)", "e": "Guardar el carrito como un texto JSON y reescribirlo entero cada vez."},
  {"m": "Redis", "t": "Sets y sorted sets", "x": "Conjuntos sin repetidos y conjuntos ordenados por puntaje.\n\nSADD agrega a un set y SISMEMBER pregunta si está. ZADD ranking 1500 ana agrega con puntaje y ZREVRANGE ranking 0 9 WITHSCORES da el top 10. Las tablas de líderes de los juegos usan sorted sets.", "u": "Seguidores, etiquetas únicas y tablas de clasificación.\n\nTu juego necesita mostrar el top 10 de jugadores por puntaje al instante.", "p": ["Un set no guarda elementos repetidos.", "ZADD agrega con un puntaje a un sorted set.", "Los sorted sets sirven para rankings."], "c": "ZADD ranking 1500 ana 1200 luis\nZREVRANGE ranking 0 9 WITHSCORES", "h": "Ranking de jugadores por puntaje.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que agrega a un sorted set es ___. (4 letras)", "e": "Ordenar en el código miles de puntajes en cada consulta."},
  {"m": "Redis", "t": "Pub/Sub", "x": "Sistema de mensajes donde unos publican y otros escuchan un canal.\n\nSUBSCRIBE canal escucha y PUBLISH canal mensaje envía a todos los suscritos. Los mensajes no se guardan: si nadie escucha, se pierden. Para colas persistentes se usan Streams (XADD).", "u": "Notificaciones en tiempo real entre servidores.\n\nTienes varios servidores de chat y un mensaje recibido en uno debe llegar a los usuarios conectados en los otros.", "p": ["PUBLISH envía un mensaje a un canal.", "SUBSCRIBE escucha un canal.", "Los mensajes de Pub/Sub no se guardan."], "c": "SUBSCRIBE chat:general\n# en otra terminal:\nPUBLISH chat:general \"Hola a todos\"", "h": "Publica un mensaje en un canal.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que envía un mensaje a un canal es ___. (7 letras)", "e": "Usar Pub/Sub para tareas que no se pueden perder."},
  {"m": "Redis", "t": "Caché con Redis", "x": "Guardar resultados costosos en Redis para responder más rápido.\n\nEl patrón cache-aside: buscas en Redis; si no está (miss), consultas la base, guardas el resultado con expiración y lo devuelves. Cuando el dato cambia, borras la clave (invalidar).", "u": "Bajar la carga de la base principal y acelerar la app.\n\nLa consulta de productos más vendidos tarda 2 segundos y se pide mil veces por minuto.", "p": ["Cache-aside busca primero en la caché.", "Un cache miss obliga a consultar la base.", "Invalidar es borrar la caché cuando el dato cambia."], "c": "import redis, json\nr = redis.Redis()\ndatos = r.get(\"top\")\nif datos is None:\n    datos = json.dumps([\"Pan\", \"Leche\"])\n    r.set(\"top\", datos, ex=300)\nprint(json.loads(datos))", "h": "Cache-aside con expiración de 5 minutos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Cuando el dato no está en la caché hay un cache ___. (4 letras)", "e": "Olvidar invalidar y mostrar datos viejos."},
  {"m": "Más allá de MongoDB", "t": "Firebase Firestore", "x": "Base de documentos en la nube de Google con tiempo real.\n\nFirestore organiza colecciones y documentos; onSnapshot avisa cada cambio en tiempo real y funciona sin conexión. La seguridad se escribe en Security Rules. Ideal con Flutter, React o Android.", "u": "Apps web y móviles que se sincronizan al instante.\n\nTu app móvil de tareas debe mostrar al instante los cambios que hace otro miembro de la familia.", "p": ["Firestore es una base de documentos de Google.", "onSnapshot escucha cambios en tiempo real.", "Firestore se protege con Security Rules."], "c": "import { onSnapshot, collection } from \"firebase/firestore\";\nonSnapshot(collection(db, \"tareas\"), (s) => console.log(s.size));", "h": "Escucha la colección de tareas en tiempo real.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función de Firestore que escucha cambios es on___. (8 letras)", "e": "Dejar las reglas abiertas a todos en producción."},
  {"m": "Más allá de MongoDB", "t": "Cassandra", "x": "Base de columnas anchas para datos enormes y escrituras masivas.\n\nApache Cassandra reparte datos entre muchos nodos sin un servidor principal y aguanta caídas. Se consulta con CQL, parecido a SQL, pero las tablas se diseñan según las consultas: la clave de partición decide en qué nodo va cada fila.", "u": "Registros de sensores, mensajes y eventos a gran escala.\n\nMiles de sensores envían lecturas cada segundo y nunca puedes dejar de recibirlas.", "p": ["Cassandra es una base de columnas anchas.", "Cassandra se consulta con CQL.", "La clave de partición decide el nodo de cada fila."], "c": "CREATE TABLE lecturas (sensor text, hora timestamp, valor double, PRIMARY KEY (sensor, hora));", "h": "Tabla de lecturas por sensor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El lenguaje de consultas de Cassandra es ___. (3 letras)", "e": "Diseñar las tablas como en SQL y luego no poder consultarlas."},
  {"m": "Más allá de MongoDB", "t": "Neo4j y Cypher", "x": "Base de grafos y su lenguaje de consultas.\n\nNeo4j guarda nodos (Persona) y relaciones ([:SIGUE]). Cypher dibuja patrones: MATCH (a:Persona)-[:SIGUE]->(b) RETURN b. Encontrar «amigos de amigos» es rápido aunque haya millones de relaciones.", "u": "Relaciones complejas: redes sociales, recomendaciones, rutas.\n\nQuieres recomendar productos que compraron personas parecidas a cada cliente.", "p": ["Neo4j guarda nodos y relaciones.", "Cypher es el lenguaje de consultas de Neo4j.", "MATCH busca patrones en el grafo."], "c": "MATCH (a:Persona {nombre: \"Ana\"})-[:SIGUE]->(b)-[:SIGUE]->(c)\nRETURN DISTINCT c.nombre", "h": "Amigos de los amigos de Ana.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El lenguaje de consultas de Neo4j es ___. (6 letras)", "e": "Usar un grafo para datos que son simples tablas."},
  {"m": "Más allá de MongoDB", "t": "DynamoDB", "x": "Base clave-valor y de documentos administrada por AWS.\n\nDynamoDB no requiere servidores: pagas por uso. Cada tabla tiene una clave de partición (y opcional de ordenación). Se consulta por clave con GetItem y Query; Scan recorre todo y es caro.", "u": "Apps serverless que escalan solas.\n\nTu app en AWS Lambda necesita una base que escale sola y cobre solo por lo que uses.", "p": ["DynamoDB es una base administrada de AWS.", "Query busca por clave de partición.", "Scan recorre toda la tabla y es costoso."], "c": "aws dynamodb get-item --table-name Usuarios --key '{\"id\": {\"S\": \"ana\"}}'", "h": "Lee un usuario por su clave.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La base NoSQL administrada de AWS es ___. (8 letras)", "e": "Usar Scan para todo y pagar de más."},
  {"m": "Más allá de MongoDB", "t": "Elasticsearch", "x": "Motor de búsqueda y análisis de texto basado en documentos.\n\nElasticsearch (y OpenSearch) indexa documentos JSON y busca texto completo con puntuación de relevancia, sinónimos y tolerancia a errores. Se usa junto a la base principal, no en su lugar. Kibana lo visualiza.", "u": "Buscadores con errores de ortografía, filtros y relevancia.\n\nTu tienda necesita un buscador que encuentre «zapatos» aunque escriban «sapatos».", "p": ["Elasticsearch busca texto completo con relevancia.", "Elasticsearch se usa junto a la base principal.", "Kibana visualiza los datos de Elasticsearch."], "c": "GET productos/_search\n{ \"query\": { \"match\": { \"nombre\": { \"query\": \"sapatos\", \"fuzziness\": \"AUTO\" } } } }", "h": "Búsqueda tolerante a errores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El motor de búsqueda de texto más usado es ___search. (7 letras)", "e": "Usar Elasticsearch como única base de datos."},
  {"m": "Más allá de MongoDB", "t": "Modelar según las consultas", "x": "Diseñar los documentos pensando en cómo se van a leer.\n\nEn SQL normalizas; en NoSQL partes de las pantallas de tu app y guardas los datos como se muestran. A veces se duplica un dato (desnormalizar) para leer en una sola consulta, aceptando actualizarlo en varios lugares.", "u": "Consultas rápidas sin JOIN en NoSQL.\n\nLa pantalla de pedidos muestra nombre del cliente y productos; en NoSQL quieres leerla con una consulta.", "p": ["En NoSQL se modela según las consultas.", "Desnormalizar es duplicar datos para leer más rápido.", "Duplicar datos obliga a actualizarlos en varios lugares."], "c": "// pedido desnormalizado\n{ _id: 1, cliente: { id: 7, nombre: \"Ana\" }, items: [{ nombre: \"Pan\", precio: 2 }] }", "h": "Pedido con datos del cliente copiados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Duplicar datos para leer más rápido es ___. (13 letras)", "e": "Copiar tablas de SQL tal cual a MongoDB."},
  {"m": "Más allá de MongoDB", "t": "Replicación y sharding", "x": "Copias de los datos en varios servidores y reparto de datos entre ellos.\n\nUn replica set de MongoDB tiene un primario que escribe y secundarios que copian; si el primario cae, se elige otro. El sharding reparte los documentos entre varios servidores usando una shard key.", "u": "No perder datos si cae un servidor y crecer sin límite.\n\nSi se daña el servidor de tu base de MongoDB, la app no puede quedarse sin datos.", "p": ["Un replica set tiene un primario y secundarios.", "Si cae el primario se elige otro.", "El sharding reparte datos con una shard key."], "c": "rs.status()\nsh.shardCollection(\"tienda.pedidos\", { clienteId: \"hashed\" })", "h": "Estado del replica set y sharding de pedidos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El grupo de copias de MongoDB se llama replica ___. (3 letras)", "e": "Elegir una shard key que manda casi todo a un solo servidor."},
  {"m": "Más allá de MongoDB", "t": "SQL y NoSQL juntos", "x": "Usar cada base en lo que mejor hace dentro del mismo proyecto.\n\nUn proyecto típico: MySQL o PostgreSQL para usuarios y pagos, Redis para sesiones y caché, MongoDB para registros o catálogo y Elasticsearch para la búsqueda. PostgreSQL también tiene JSONB para documentos dentro de SQL.", "u": "Combinar transacciones, caché y datos flexibles.\n\nTu proyecto FinanBot guarda transacciones en MySQL y quieres pasar a MongoDB solo el historial de conversaciones del chatbot.", "p": ["Un proyecto puede usar SQL y NoSQL a la vez.", "Redis suele usarse para sesiones y caché.", "PostgreSQL tiene JSONB para guardar documentos."], "c": "# usuarios y movimientos → MySQL (finanbot_db)\n# conversaciones del chatbot → MongoDB\n# sesiones → Redis", "h": "Cada dato en la base que mejor le sirve.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de columna de PostgreSQL para documentos es ___. (5 letras)", "e": "Sincronizar las bases a mano sin una fuente de verdad clara."},
  {"m": "MongoDB a fondo", "t": "Operadores lógicos", "x": "Combinar condiciones con $and, $or y $not.\n\n{ $or: [{ ciudad: \"Bogotá\" }, { ciudad: \"Cali\" }] } trae los de cualquiera de las dos. Varias condiciones en el mismo objeto ya son un $and implícito. $nor niega todas.", "u": "Buscar documentos que cumplan varias reglas a la vez.\n\nQuieres los clientes de Bogotá o de Medellín en una sola consulta.", "p": ["$or trae documentos que cumplan alguna condición.", "Varias condiciones en el mismo objeto funcionan como $and.", "$not niega una condición."], "c": "db.clientes.find({ $or: [{ ciudad: \"Bogotá\" }, { ciudad: \"Medellín\" }] }).count()", "h": "Cuenta clientes de dos ciudades.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador para «una condición u otra» es $___ (2 letras)", "e": "Escribir dos veces la misma clave en un objeto y que una pise a la otra."},
  {"m": "MongoDB a fondo", "t": "$in y $nin", "x": "Buscar valores que estén (o no) dentro de una lista.\n\n{ estado: { $in: [\"pagado\", \"enviado\"] } } es más corto que un $or con la misma clave. $nin trae los que no están en la lista.", "u": "Filtrar por varias categorías o estados a la vez.\n\nQuieres los pedidos cuyo estado sea pagado, enviado o entregado.", "p": ["$in busca valores dentro de una lista.", "$nin trae los que no están en la lista.", "$in es más corto que $or sobre la misma clave."], "c": "db.pedidos.find({ estado: { $in: [\"pagado\", \"enviado\"] } }).count()", "h": "Cuenta pedidos en dos estados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador para «está en la lista» es $___ (2 letras)", "e": "Encadenar muchos $or sobre la misma clave."},
  {"m": "MongoDB a fondo", "t": "$exists y $type", "x": "Buscar documentos según si tienen un campo o de qué tipo es.\n\n{ telefono: { $exists: false } } trae los que no tienen teléfono. { precio: { $type: \"string\" } } encuentra precios guardados como texto por error.", "u": "Encontrar datos incompletos o mal guardados.\n\nAlgunos productos tienen el precio guardado como texto y rompen tus sumas.", "p": ["$exists revisa si un campo existe.", "$type revisa de qué tipo es un campo.", "Sirven para encontrar datos mal guardados."], "c": "db.productos.find({ precio: { $type: \"string\" } }).count()", "h": "Cuenta precios guardados como texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que revisa si un campo existe es $___ (6 letras)", "e": "Suponer que todos los documentos tienen los mismos campos."},
  {"m": "MongoDB a fondo", "t": "Consultas en arreglos", "x": "Buscar dentro de campos que son listas.\n\n{ etiquetas: \"oferta\" } busca si el arreglo contiene el valor. $all exige varios, $size el tamaño exacto y $elemMatch que un mismo elemento cumpla varias condiciones.", "u": "Filtrar por etiquetas, notas o productos de un pedido.\n\nQuieres los pedidos que tienen algún producto con cantidad mayor a 5 y precio menor a 10 000 en el mismo producto.", "p": ["Buscar un valor en un arreglo es como buscar un campo normal.", "$all exige que estén todos los valores.", "$elemMatch aplica varias condiciones al mismo elemento."], "c": "db.pedidos.find({ items: { $elemMatch: { cantidad: { $gt: 5 }, precio: { $lt: 10000 } } } }).count()", "h": "Cuenta pedidos con un ítem que cumple dos condiciones.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador para que un mismo elemento cumpla varias condiciones es $___ (9 letras)", "e": "Usar dos condiciones sueltas y que las cumplan elementos distintos."},
  {"m": "MongoDB a fondo", "t": "Actualizar arreglos", "x": "Agregar o quitar elementos de un campo de lista.\n\n$push agrega al final, $addToSet agrega solo si no está, $pull quita los que coinciden y $pop quita el primero o el último.", "u": "Manejar listas de etiquetas, favoritos o comentarios.\n\nAl marcar un curso como favorito varias veces se repite en la lista.", "p": ["$push agrega un elemento a un arreglo.", "$addToSet no agrega repetidos.", "$pull quita los elementos que coinciden."], "c": "db.usuarios.updateOne({ _id: 1 }, { $addToSet: { favoritos: \"react\" } })", "h": "Agrega un favorito sin repetir.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador que agrega sin repetir es $___ (8 letras)", "e": "Leer el arreglo completo, cambiarlo en el código y guardarlo entero."},
  {"m": "MongoDB a fondo", "t": "$inc y $unset", "x": "Sumar a un número y borrar un campo de un documento.\n\n{ $inc: { visitas: 1 } } suma 1 de forma segura aunque haya muchas peticiones a la vez. { $unset: { telefono: \"\" } } elimina el campo.", "u": "Contar visitas o quitar datos que ya no se usan.\n\nCada visita a un producto debe sumar 1 a su contador sin perder visitas cuando llegan muchas a la vez.", "p": ["$inc suma a un campo numérico.", "$inc es seguro con muchas peticiones simultáneas.", "$unset elimina un campo del documento."], "c": "db.productos.updateOne({ _id: 7 }, { $inc: { visitas: 1 } })", "h": "Suma una visita.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El operador para sumar a un número es $___ (3 letras)", "e": "Leer el contador, sumar en el código y guardarlo, perdiendo visitas."},
  {"m": "MongoDB a fondo", "t": "upsert", "x": "Actualizar si existe o crear si no existe, en una sola operación.\n\nupdateOne({ usuario: 5 }, { $set: { tema: \"oscuro\" } }, { upsert: true }) actualiza o inserta. Evita el «leer y luego decidir» que falla con peticiones simultáneas.", "u": "Guardar preferencias o contadores sin revisar antes si existen.\n\nQuieres guardar el tema elegido por un usuario, exista o no su documento de preferencias.", "p": ["upsert actualiza si existe y crea si no.", "Se activa con la opción upsert: true.", "Evita revisar antes si el documento existe."], "c": "db.prefs.updateOne({ usuario: 5 }, { $set: { tema: \"oscuro\" } }, { upsert: true })", "h": "Guarda la preferencia exista o no.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción para crear si no existe es ___: true (6 letras)", "e": "Hacer find y luego insert y crear duplicados con dos peticiones a la vez."},
  {"m": "MongoDB a fondo", "t": "replaceOne", "x": "Reemplazar un documento completo por otro.\n\nreplaceOne({ _id: 3 }, documentoNuevo) cambia todo salvo el _id: los campos que no estén en el nuevo desaparecen. Para cambiar solo algunos campos usa updateOne con $set.", "u": "Guardar la versión nueva de un documento entero.\n\nUsaste replaceOne para cambiar el nombre y el usuario perdió su correo y su foto.", "p": ["replaceOne reemplaza el documento entero.", "Los campos que no estén en el nuevo se pierden.", "Para cambiar algunos campos se usa $set."], "c": "db.usuarios.replaceOne({ _id: 3 }, { nombre: \"Ana\", correo: \"ana@correo.com\" })", "h": "Reemplaza el documento completo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La operación que reemplaza un documento entero es ___One (7 letras)", "e": "Usar replaceOne para cambiar un solo campo."},
  {"m": "MongoDB a fondo", "t": "findOneAndUpdate", "x": "Actualizar un documento y recibirlo en la misma operación.\n\nfindOneAndUpdate({ _id: \"factura\" }, { $inc: { n: 1 } }, { returnDocument: \"after\" }) suma y devuelve el número nuevo de forma atómica: nunca dos facturas con el mismo número.", "u": "Tomar turnos, reservar cupos o generar consecutivos sin choques.\n\nDebes generar números de factura consecutivos sin que dos ventas reciban el mismo número.", "p": ["findOneAndUpdate actualiza y devuelve el documento.", "returnDocument: \"after\" devuelve la versión nueva.", "Es atómico: evita choques entre peticiones."], "c": "db.contadores.findOneAndUpdate({ _id: \"factura\" }, { $inc: { n: 1 } }, { returnDocument: \"after\" })", "h": "Genera el siguiente número de factura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para recibir la versión nueva se usa returnDocument: \"___\" (5 letras, en inglés)", "e": "Leer el último número y sumarle 1 en el código."},
  {"m": "MongoDB a fondo", "t": "countDocuments y distinct", "x": "Contar documentos y listar valores únicos.\n\ncountDocuments({ activo: true }) cuenta los que cumplen el filtro. distinct(\"ciudad\") devuelve las ciudades sin repetir. Para conteos aproximados rápidos existe estimatedDocumentCount.", "u": "Hacer resúmenes rápidos sin traer todos los datos.\n\nQuieres saber en qué ciudades tienes clientes, sin repetir ninguna.", "p": ["countDocuments cuenta los documentos que cumplen un filtro.", "distinct lista los valores únicos de un campo.", "estimatedDocumentCount da un conteo rápido aproximado."], "c": "db.clientes.distinct(\"ciudad\")", "h": "Lista las ciudades sin repetir.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que lista valores únicos es ___ (8 letras)", "e": "Traer todos los documentos al código solo para contarlos."},
  {"m": "MongoDB a fondo", "t": "Buscar texto con regex", "x": "Filtrar con expresiones regulares en MongoDB.\n\n{ nombre: { $regex: \"^ana\", $options: \"i\" } } busca nombres que empiezan con «ana» sin importar mayúsculas. Solo las regex que empiezan con ^ aprovechan bien los índices.", "u": "Hacer búsquedas parciales por nombre.\n\nTu buscador debe encontrar «Andrés» cuando alguien escribe «and».", "p": ["$regex busca con expresiones regulares.", "$options: \"i\" ignora mayúsculas.", "Las regex con ^ al inicio aprovechan mejor los índices."], "c": "db.clientes.find({ nombre: { $regex: \"^and\", $options: \"i\" } }, { nombre: 1, _id: 0 })", "h": "Busca nombres que empiezan con and.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción para ignorar mayúsculas en $regex es \"___\" (1 letra)", "e": "Usar regex sin ^ en colecciones enormes y hacerlas lentísimas."},
  {"m": "MongoDB a fondo", "t": "Paginación en MongoDB", "x": "Traer los resultados por páginas.\n\nskip(20).limit(10) es simple pero se vuelve lento con páginas lejanas. La paginación por cursor usa el último _id visto: find({ _id: { $gt: ultimo } }).limit(10), que siempre es rápida.", "u": "Mostrar listas grandes sin cargarlo todo.\n\nTu lista de productos va rápida en la página 1 pero tarda mucho en la página 5000.", "p": ["skip y limit paginan de forma sencilla.", "skip se vuelve lento con páginas lejanas.", "La paginación por cursor usa el último valor visto."], "c": "db.productos.find({ _id: { $gt: ObjectId(\"665f0c...\") } }).sort({ _id: 1 }).limit(10)", "h": "Trae la siguiente página por cursor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para saltar documentos se usa el método ___ (4 letras)", "e": "Usar skip de millones de documentos."},
  {"m": "MongoDB a fondo", "t": "ObjectId", "x": "Identificador por defecto de cada documento de MongoDB.\n\nUn ObjectId tiene 12 bytes y empieza con la fecha de creación: getTimestamp() la devuelve. Se busca con ObjectId(\"...\"), no con el texto solo.", "u": "Entender qué es _id y cómo usarlo.\n\nBuscas un documento por su _id escribiendo solo el texto y no lo encuentra.", "p": ["ObjectId es el identificador por defecto de MongoDB.", "El ObjectId incluye la fecha de creación.", "Para buscar por _id se usa ObjectId(...)."], "c": "ObjectId(\"665f0c2b9d3e4a1b2c3d4e5f\").getTimestamp()", "h": "Muestra la fecha de creación de un id.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que da la fecha de un ObjectId es get___ (9 letras, en inglés)", "e": "Buscar un _id como texto sin convertirlo a ObjectId."},
  {"m": "MongoDB a fondo", "t": "Fechas en MongoDB", "x": "Guardar fechas con su tipo Date para poder filtrarlas y ordenarlas.\n\nGuarda new Date() o ISODate(\"2026-11-22\"), no texto. Así funcionan { fecha: { $gte: inicio, $lt: fin } } y en agregación $dateToString o $month. Se guardan en UTC.", "u": "Hacer reportes por día, mes o rango de fechas.\n\nGuardaste las fechas como texto «22/11/2026» y ahora no puedes filtrar por mes.", "p": ["Las fechas se guardan con el tipo Date.", "Con Date se pueden filtrar rangos de fechas.", "MongoDB guarda las fechas en UTC."], "c": "db.ventas.countDocuments({ fecha: { $gte: ISODate(\"2026-11-01\"), $lt: ISODate(\"2026-12-01\") } })", "h": "Cuenta las ventas de noviembre.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En MongoDB las fechas se guardan en la zona ___ (3 letras)", "e": "Guardar fechas como texto en formatos distintos."},
  {"m": "MongoDB a fondo", "t": "$match y $project", "x": "Filtrar y elegir campos dentro de un pipeline de agregación.\n\n$match filtra como find (ponlo al principio para usar índices) y $project elige, renombra o calcula campos: { $project: { nombre: 1, total: { $multiply: [\"$precio\", \"$cantidad\"] } } }.", "u": "Preparar los datos antes de agruparlos.\n\nEn tu pipeline quieres calcular el total de cada línea multiplicando precio por cantidad.", "p": ["$match filtra dentro de una agregación.", "$match al principio aprovecha los índices.", "$project elige o calcula campos."], "c": "db.items.aggregate([{ $project: { _id: 0, total: { $multiply: [\"$precio\", \"$cantidad\"] } } }, { $limit: 1 }])", "h": "Calcula el total de una línea.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que filtra en una agregación es $___ (5 letras)", "e": "Poner $match al final del pipeline y procesar datos de más."},
  {"m": "MongoDB a fondo", "t": "$unwind", "x": "Convertir cada elemento de un arreglo en un documento aparte.\n\nUn pedido con 3 ítems se vuelve 3 documentos con { $unwind: \"$items\" }. Luego puedes agrupar por producto con $group.", "u": "Agrupar o contar los elementos que están dentro de listas.\n\nQuieres saber qué producto se vendió más, pero los productos están dentro del arreglo items de cada pedido.", "p": ["$unwind separa cada elemento de un arreglo.", "Cada elemento se vuelve un documento.", "Se usa antes de agrupar elementos de listas."], "c": "db.pedidos.aggregate([{ $unwind: \"$items\" }, { $count: \"lineas\" }])", "h": "Cuenta todas las líneas de pedido.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que separa los elementos de un arreglo es $___ (6 letras)", "e": "Olvidar que los documentos sin el arreglo desaparecen con $unwind."},
  {"m": "MongoDB a fondo", "t": "$facet", "x": "Ejecutar varios pipelines sobre los mismos datos en una sola consulta.\n\n{ $facet: { resultados: [{ $limit: 10 }], total: [{ $count: \"n\" }], porCategoria: [{ $group: ... }] } } devuelve todo en un documento.", "u": "Traer resultados, totales y filtros de una tienda en un solo viaje.\n\nTu tienda necesita la página de productos, el total y el conteo por categoría, y haces 3 consultas.", "p": ["$facet ejecuta varios pipelines a la vez.", "Devuelve un documento con cada resultado.", "Sirve para resultados más totales en una consulta."], "c": "db.productos.aggregate([{ $facet: { total: [{ $count: \"n\" }] } }])", "h": "Calcula el total con $facet.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que ejecuta varios pipelines a la vez es $___ (5 letras)", "e": "Hacer muchas consultas separadas para una misma página."},
  {"m": "MongoDB a fondo", "t": "Búsqueda de texto", "x": "Índice de texto para buscar palabras en campos largos.\n\ndb.productos.createIndex({ nombre: \"text\", descripcion: \"text\" }) y find({ $text: { $search: \"teclado inalámbrico\" } }). Para búsquedas avanzadas en Atlas existe Atlas Search.", "u": "Hacer un buscador de productos o artículos.\n\nQuieres que tu buscador encuentre productos por palabras en el nombre o en la descripción.", "p": ["Un índice text permite buscar palabras.", "$text con $search hace la búsqueda.", "Atlas Search ofrece búsquedas más avanzadas."], "c": "db.productos.find({ $text: { $search: \"teclado\" } }).count()", "h": "Cuenta productos con la palabra teclado.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tipo de índice para buscar palabras es \"___\" (4 letras, en inglés)", "e": "Usar regex sin índice como buscador de una tienda grande."},
  {"m": "MongoDB a fondo", "t": "Exportar e importar datos", "x": "Herramientas para respaldar y mover datos de MongoDB.\n\nmongodump y mongorestore respaldan y restauran en formato BSON. mongoexport e mongoimport trabajan con JSON y CSV: mongoimport --db tienda --collection productos --file productos.json --jsonArray.", "u": "Hacer respaldos o cargar datos desde JSON y CSV.\n\nTe pasaron un archivo productos.json y quieres cargarlo en una colección.", "p": ["mongodump respalda una base en formato BSON.", "mongorestore restaura un respaldo.", "mongoimport carga archivos JSON o CSV."], "c": "mongoimport --db tienda --collection productos --file productos.json --jsonArray", "h": "Carga un JSON en la colección.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La herramienta que respalda en BSON es mongo___ (4 letras)", "e": "Copiar documentos a mano uno por uno."},
  {"m": "MongoDB a fondo", "t": "Collation", "x": "Reglas de idioma para comparar y ordenar texto.\n\nsort({ nombre: 1 }).collation({ locale: \"es\", strength: 1 }) ordena «Ángela» junto a «Ana» e ignora mayúsculas y tildes. También sirve en índices para búsquedas sin distinguir mayúsculas.", "u": "Ordenar bien palabras con tildes y sin importar mayúsculas.\n\nAl ordenar nombres, los que empiezan con Á quedan al final de la lista.", "p": ["Collation define reglas de idioma para el texto.", "locale: \"es\" usa las reglas del español.", "strength: 1 ignora mayúsculas y tildes."], "c": "db.clientes.find().sort({ nombre: 1 }).collation({ locale: \"es\" }).limit(2)", "h": "Ordena nombres en español.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las reglas de idioma para ordenar texto se llaman ___ (9 letras, en inglés)", "e": "Ordenar texto en español con las reglas por defecto."},
  {"m": "Modelado y rendimiento", "t": "Embeber o referenciar", "x": "Decidir si guardar datos relacionados dentro del documento o en otra colección.\n\nEmbebe lo que se lee junto y es limitado (direcciones de un cliente). Referencia lo que crece sin límite o se comparte (comentarios de un post, productos de muchos pedidos).", "u": "Diseñar colecciones rápidas y fáciles de mantener.\n\nUn post puede tener 50 000 comentarios.", "p": ["Se embebe lo que se lee junto y es limitado.", "Se referencia lo que crece sin límite.", "Lo que comparten muchos documentos se referencia."], "c": "db.comentarios.find({ post_id: 12 }).limit(1)", "h": "Trae un comentario por referencia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Guardar datos dentro del mismo documento se llama ___ (7 letras)", "e": "Embeber listas que crecen sin límite."},
  {"m": "Modelado y rendimiento", "t": "Uno a muchos", "x": "Modelar una relación como un cliente con sus pedidos.\n\nPocos (direcciones): embebidos. Cientos (productos de una categoría): arreglo de ids. Miles o más (registros de un sensor): cada hijo guarda el id del padre.", "u": "Elegir el diseño según cuántos «muchos» hay.\n\nUn sensor envía 10 000 lecturas al día.", "p": ["Con pocos hijos se embeben.", "Con cientos de hijos se puede guardar un arreglo de ids.", "Con miles de hijos cada uno guarda el id del padre."], "c": "db.lecturas.countDocuments({ sensor_id: \"s1\" })", "h": "Cuenta las lecturas de un sensor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con miles de hijos, cada hijo guarda el ___ del padre (2 letras)", "e": "Usar la misma solución sin importar cuántos hijos hay."},
  {"m": "Modelado y rendimiento", "t": "Muchos a muchos", "x": "Modelar relaciones como estudiantes y cursos.\n\nCada estudiante guarda un arreglo de ids de cursos (y opcionalmente cada curso los de estudiantes). Si la relación tiene datos propios (nota, fecha), usa una colección intermedia.", "u": "Guardar relaciones donde ambos lados tienen varios.\n\nCada inscripción tiene una nota y una fecha propias.", "p": ["En muchos a muchos se guardan arreglos de ids.", "Si la relación tiene datos propios se usa una colección intermedia.", "Se puede guardar la relación en uno o en ambos lados."], "c": "db.inscripciones.findOne({ estudiante: 7, curso: \"react\" })", "h": "Busca una inscripción.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Si la relación tiene datos propios se usa una colección ___ (10 letras)", "e": "Duplicar los datos del curso en cada estudiante."},
  {"m": "Modelado y rendimiento", "t": "Patrón bucket", "x": "Agrupar muchos datos pequeños en documentos por intervalo.\n\nEn lugar de un documento por lectura, un documento por sensor y hora con un arreglo de 60 lecturas. Menos documentos, índices más pequeños y consultas más rápidas.", "u": "Guardar lecturas o eventos sin millones de documentos diminutos.\n\nTu colección tiene 500 millones de documentos de una lectura cada uno y los índices ya no caben en memoria.", "p": ["El patrón bucket agrupa datos por intervalo.", "Reduce la cantidad de documentos.", "Es útil para series de tiempo."], "c": "db.lecturas.findOne({ sensor: \"s1\", hora: ISODate(\"2026-11-22T10:00:00Z\") }).valores.length", "h": "Cuenta las lecturas de una hora.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El patrón que agrupa datos por intervalo se llama ___ (6 letras, en inglés)", "e": "Crear un documento por cada dato diminuto."},
  {"m": "Modelado y rendimiento", "t": "Desnormalizar", "x": "Copiar algunos datos en varios documentos para leer más rápido.\n\nGuardas el nombre del autor dentro de cada post además de su id. Lees más rápido, pero si el autor cambia de nombre hay que actualizar las copias.", "u": "Mostrar listas sin hacer $lookup en cada consulta.\n\nTu lista de posts hace un $lookup para mostrar el nombre del autor y va lenta.", "p": ["Desnormalizar es copiar datos para leer más rápido.", "Las copias hay que actualizarlas si cambian.", "Conviene con datos que cambian poco."], "c": "db.posts.findOne({}, { autor: 1, _id: 0 })", "h": "Muestra el autor copiado en el post.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Copiar datos en varios documentos se llama ___ (12 letras)", "e": "Copiar datos que cambian a cada rato."},
  {"m": "Modelado y rendimiento", "t": "Versionar el esquema", "x": "Guardar en cada documento qué versión de esquema tiene.\n\nAgregas schemaVersion: 2. Tu código entiende la 1 y la 2, y actualiza los documentos viejos poco a poco al leerlos o con un script en segundo plano.", "u": "Cambiar la forma de los datos sin migrar todo de golpe.\n\nCambiaste el campo nombre por nombre y apellido y tienes 3 millones de documentos viejos.", "p": ["schemaVersion indica la forma del documento.", "El código puede entender varias versiones.", "Los documentos viejos se migran poco a poco."], "c": "db.usuarios.countDocuments({ schemaVersion: { $ne: 2 } })", "h": "Cuenta los documentos por migrar.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El campo que indica la versión del documento suele llamarse schema___ (7 letras, en inglés)", "e": "Cambiar el esquema y romper todos los documentos viejos."},
  {"m": "Modelado y rendimiento", "t": "explain()", "x": "Ver cómo ejecuta MongoDB una consulta y si usa índices.\n\nfind(...).explain(\"executionStats\") muestra si fue COLLSCAN (revisó toda la colección) o IXSCAN (usó un índice) y cuántos documentos examinó frente a los que devolvió.", "u": "Descubrir por qué una consulta es lenta.\n\nUna consulta tarda 4 segundos y quieres saber si está usando un índice.", "p": ["explain muestra cómo se ejecuta una consulta.", "COLLSCAN significa que revisó toda la colección.", "IXSCAN significa que usó un índice."], "c": "db.ventas.find({ cliente: 7 }).explain(\"executionStats\").queryPlanner.winningPlan.stage", "h": "Muestra la estrategia de la consulta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La etapa que revisa toda la colección es ___ (8 letras)", "e": "Crear índices al azar sin revisar explain."},
  {"m": "Modelado y rendimiento", "t": "Índices compuestos y regla ESR", "x": "Índices de varios campos y en qué orden ponerlos.\n\nRegla ESR: primero los campos de igualdad (Equality), luego los de orden (Sort) y al final los de rango (Range). Para find({ tienda: 1, precio: { $gt: 5 } }).sort({ fecha: -1 }) el índice es { tienda: 1, fecha: -1, precio: 1 }.", "u": "Que una consulta con filtro y orden use un solo índice.\n\nTu consulta filtra por tienda, ordena por fecha y filtra un rango de precios.", "p": ["Un índice compuesto tiene varios campos.", "La regla ESR ordena igualdad, orden y rango.", "Un buen índice compuesto evita ordenar en memoria."], "c": "db.ventas.createIndex({ tienda: 1, fecha: -1, precio: 1 })", "h": "Crea el índice siguiendo ESR.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La regla del orden de un índice compuesto se llama ___ (3 letras)", "e": "Poner primero el campo de rango y obligar a MongoDB a ordenar en memoria."},
  {"m": "Modelado y rendimiento", "t": "Índices únicos", "x": "Índice que impide guardar dos documentos con el mismo valor.\n\ncreateIndex({ email: 1 }, { unique: true }). Un insert repetido falla con el error E11000 duplicate key. Con partialFilterExpression puedes aplicarlo solo a algunos documentos.", "u": "Que no se repitan correos o códigos.\n\nTienes usuarios repetidos con el mismo correo porque dos registros llegaron a la vez.", "p": ["Un índice único impide valores repetidos.", "Un repetido da el error E11000.", "El índice se crea con unique: true."], "c": "db.usuarios.createIndex({ email: 1 }, { unique: true })", "h": "Impide correos repetidos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción para un índice sin repetidos es ___: true (6 letras, en inglés)", "e": "Revisar repetidos solo en el código y no en la base."},
  {"m": "Modelado y rendimiento", "t": "Índices TTL", "x": "Índices que borran solos los documentos después de un tiempo.\n\ncreateIndex({ creado: 1 }, { expireAfterSeconds: 3600 }) borra los documentos una hora después de la fecha del campo creado. El campo debe ser de tipo Date.", "u": "Borrar sesiones, códigos o logs vencidos sin tareas programadas.\n\nLos códigos de verificación deben desaparecer 15 minutos después de crearse.", "p": ["Un índice TTL borra documentos vencidos.", "expireAfterSeconds define el tiempo de vida.", "El campo del índice TTL debe ser una fecha."], "c": "db.codigos.createIndex({ creado: 1 }, { expireAfterSeconds: 900 })", "h": "Borra los códigos a los 15 minutos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción del tiempo de vida es expireAfter___ (7 letras, en inglés)", "e": "Guardar el campo de fecha como texto y que el TTL no borre nada."},
  {"m": "Modelado y rendimiento", "t": "Índices parciales", "x": "Índices que solo incluyen los documentos que cumplen un filtro.\n\ncreateIndex({ cliente: 1 }, { partialFilterExpression: { estado: \"pendiente\" } }) indexa solo pedidos pendientes. Ocupa menos memoria; la consulta debe incluir ese filtro.", "u": "Tener índices pequeños para las consultas que importan.\n\nSolo consultas por cliente los pedidos pendientes, que son el 2 % del total.", "p": ["Un índice parcial solo incluye algunos documentos.", "Ocupa menos memoria que uno completo.", "La consulta debe incluir el filtro del índice."], "c": "db.pedidos.createIndex({ cliente: 1 }, { partialFilterExpression: { estado: \"pendiente\" } })", "h": "Indexa solo los pendientes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción de un índice parcial es partialFilter___ (10 letras, en inglés)", "e": "Indexar toda la colección para consultar una pequeña parte."},
  {"m": "Modelado y rendimiento", "t": "Transacciones en MongoDB", "x": "Varias operaciones en varios documentos que se aplican todas o ninguna.\n\nCon una sesión: session.withTransaction(async () => { ...updateOne(..., { session }) ... }). Funcionan en réplicas (Atlas siempre lo es). Si el diseño embebido lo permite, mejor una sola operación atómica.", "u": "Transferencias y compras que tocan varias colecciones.\n\nAl transferir puntos, debes restar a un usuario y sumar a otro sin que quede a medias.", "p": ["Una transacción aplica todo o nada.", "Las operaciones usan la misma sesión.", "Necesitan un replica set."], "c": "session.withTransaction(async () => { /* restar y sumar con { session } */ })", "h": "Agrupa la transferencia.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las transacciones necesitan un replica ___ (3 letras, en inglés)", "e": "Usar transacciones para todo en lugar de un buen diseño."},
  {"m": "Modelado y rendimiento", "t": "Write concern y read preference", "x": "Opciones de cuántas réplicas confirman una escritura y de dónde se lee.\n\nw: \"majority\" espera que la mayoría de réplicas guarde el dato (más seguro). readPreference: \"secondaryPreferred\" lee de réplicas secundarias para repartir la carga, con datos quizá algo atrasados.", "u": "Elegir entre velocidad y seguridad de los datos.\n\nNo puedes perder ningún pago aunque se caiga el servidor principal justo después de guardarlo.", "p": ["w: \"majority\" espera la confirmación de la mayoría.", "readPreference elige de qué réplica leer.", "Leer de secundarias puede dar datos algo atrasados."], "c": "db.pagos.insertOne({ monto: 50000 }, { writeConcern: { w: \"majority\" } })", "h": "Guarda un pago con confirmación de la mayoría.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El write concern más seguro es w: \"___\" (8 letras, en inglés)", "e": "Leer de secundarias datos que deben estar al día al instante."},
  {"m": "Modelado y rendimiento", "t": "Change streams", "x": "Escuchar en tiempo real los cambios de una colección.\n\nconst flujo = db.pedidos.watch([{ $match: { operationType: \"insert\" } }]); flujo.on(\"change\", c => ...). Funciona en replica sets y puede retomar donde quedó con el resume token.", "u": "Notificar, sincronizar o actualizar pantallas cuando cambian los datos.\n\nQuieres que el panel de cocina muestre cada pedido nuevo al instante sin consultar la base cada segundo.", "p": ["Un change stream avisa cambios en tiempo real.", "Se crea con el método watch.", "El resume token permite retomar donde quedó."], "c": "db.pedidos.watch([{ $match: { operationType: \"insert\" } }])", "h": "Escucha los pedidos nuevos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El método que crea un change stream es ___() (5 letras, en inglés)", "e": "Consultar la base cada segundo para ver si hay cambios."},
  {"m": "Modelado y rendimiento", "t": "Colecciones time series", "x": "Colecciones optimizadas para datos con fecha.\n\ndb.createCollection(\"metricas\", { timeseries: { timeField: \"ts\", metaField: \"sensor\", granularity: \"minutes\" } }). MongoDB agrupa por dentro (como un bucket) y comprime.", "u": "Guardar métricas y lecturas ocupando poco espacio.\n\nGuardas la temperatura de 500 sensores cada minuto y la colección crece muchísimo.", "p": ["Las colecciones time series guardan datos con fecha.", "timeField indica el campo de fecha.", "MongoDB las agrupa y comprime por dentro."], "c": "db.createCollection(\"metricas\", { timeseries: { timeField: \"ts\", metaField: \"sensor\" } })", "h": "Crea una colección de series de tiempo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El campo de fecha de una serie de tiempo se indica en time___ (5 letras, en inglés)", "e": "Guardar millones de métricas en una colección normal sin pensar."},
  {"m": "Modelado y rendimiento", "t": "GridFS", "x": "Forma de guardar archivos grandes dentro de MongoDB.\n\nUn documento no puede pasar de 16 MB. GridFS parte el archivo en trozos (fs.chunks) y guarda sus datos en fs.files. Para la mayoría de apps es mejor un almacenamiento de objetos (S3) y guardar solo la URL.", "u": "Guardar archivos de más de 16 MB.\n\nDebes guardar videos de 200 MB y un documento de MongoDB no puede pasar de cierto tamaño.", "p": ["Un documento de MongoDB no puede pasar de 16 MB.", "GridFS divide archivos grandes en trozos.", "Muchas veces es mejor guardar el archivo fuera y solo la URL."], "c": "db.fs.files.countDocuments()", "h": "Cuenta los archivos guardados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El tamaño máximo de un documento es ___ MB (2 dígitos)", "e": "Guardar imágenes en base64 dentro de documentos normales."},
  {"m": "Modelado y rendimiento", "t": "Atlas Search", "x": "Búsqueda de texto avanzada de MongoDB Atlas.\n\nCreas un índice de búsqueda en Atlas y usas la etapa $search en agregación, con fuzzy para tolerar errores («telcado» encuentra «teclado») y autocompletado.", "u": "Buscar con tolerancia a errores, sinónimos y relevancia.\n\nTu buscador no encuentra nada cuando el usuario escribe «telcado» en lugar de «teclado».", "p": ["Atlas Search usa la etapa $search.", "fuzzy tolera errores de escritura.", "Permite autocompletado y ordenar por relevancia."], "c": "db.productos.aggregate([{ $search: { text: { query: \"telcado\", path: \"nombre\", fuzzy: {} } } }, { $limit: 1 }])", "h": "Busca tolerando errores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción que tolera errores de escritura es ___ (5 letras, en inglés)", "e": "Pedir a los usuarios que escriban perfecto."},
  {"m": "Modelado y rendimiento", "t": "Búsqueda vectorial", "x": "Buscar documentos por significado usando vectores (embeddings).\n\nUn modelo de IA convierte cada texto en un vector; Atlas Vector Search ($vectorSearch) encuentra los más parecidos a la pregunta. Así «zapatos para correr» encuentra «tenis deportivos».", "u": "Hacer buscadores semánticos y apps con IA.\n\nQuieres que tu buscador entienda que «zapatos para correr» y «tenis deportivos» significan lo mismo.", "p": ["Un embedding representa el significado de un texto como vector.", "$vectorSearch busca los vectores más parecidos.", "Permite buscar por significado y no solo por palabras."], "c": "db.productos.aggregate([{ $vectorSearch: { index: \"vec\", path: \"embedding\", queryVector: v, numCandidates: 50, limit: 3 } }])", "h": "Busca los tres productos más parecidos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La representación numérica del significado de un texto se llama ___ (9 letras, en inglés)", "e": "Comparar vectores creados con modelos distintos."},
  {"m": "Modelado y rendimiento", "t": "Seguridad en MongoDB", "x": "Proteger tu base con usuarios, roles y red.\n\nActiva autenticación, crea usuarios con el mínimo rol necesario (readWrite en una sola base), restringe IP en Atlas (Network Access), usa TLS y nunca expongas el puerto 27017 sin contraseña.", "u": "Que nadie de internet lea o borre tus datos.\n\nMiles de bases MongoDB fueron borradas por estar en internet sin contraseña.", "p": ["Cada app debe tener su usuario con el rol mínimo.", "En Atlas se restringen las IP permitidas.", "Nunca se expone MongoDB sin autenticación."], "c": "db.createUser({ user: \"app\", pwd: passwordPrompt(), roles: [{ role: \"readWrite\", db: \"tienda\" }] })", "h": "Crea un usuario con el rol mínimo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El rol para leer y escribir en una base es read___ (5 letras, en inglés)", "e": "Usar el usuario administrador en la app."},
  {"m": "Modelado y rendimiento", "t": "Patrón de atributos", "x": "Guardar características variables como una lista de pares clave-valor.\n\nEn vez de talla, color, voltaje… como campos sueltos, guardas atributos: [{ k: \"color\", v: \"rojo\" }, { k: \"talla\", v: \"M\" }] y creas un solo índice { \"atributos.k\": 1, \"atributos.v\": 1 }.", "u": "Buscar e indexar productos que tienen campos distintos.\n\nTu tienda vende ropa, celulares y comida, cada uno con características distintas, y necesitarías 40 índices.", "p": ["El patrón de atributos guarda pares clave-valor en un arreglo.", "Un solo índice sirve para todos los atributos.", "Es útil cuando cada producto tiene campos distintos."], "c": "db.productos.find({ atributos: { $elemMatch: { k: \"color\", v: \"rojo\" } } }).count()", "h": "Cuenta los productos rojos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En el patrón de atributos cada par tiene una clave k y un valor ___ (1 letra)", "e": "Crear un índice por cada característica posible."},
  {"m": "Redis y otras bases en producción", "t": "Redis Streams", "x": "Estructura de Redis para registros de eventos con consumidores.\n\nXADD pedidos * id 42 agrega un evento; XREADGROUP lee como parte de un grupo de consumidores y XACK confirma que se procesó. A diferencia de Pub/Sub, los eventos quedan guardados.", "u": "Procesar eventos en orden y sin perderlos.\n\nCon Pub/Sub pierdes los mensajes si el consumidor está apagado.", "p": ["Un stream guarda eventos en orden.", "XADD agrega un evento al stream.", "A diferencia de Pub/Sub, los eventos quedan guardados."], "c": "XADD pedidos * id 42 total 50000", "h": "Agrega un evento al stream.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que agrega un evento a un stream es ___ (4 letras)", "e": "Usar Pub/Sub cuando no puedes perder mensajes."},
  {"m": "Redis y otras bases en producción", "t": "Contadores con INCR", "x": "Sumar de forma atómica a un número guardado en Redis.\n\nINCR visitas:home suma 1 y devuelve el nuevo valor; INCRBY suma otra cantidad. Es atómico: miles de peticiones a la vez nunca pierden un conteo.", "u": "Contar visitas, likes o intentos muy rápido.\n\nNecesitas contar las visitas de cada página con miles de visitas por segundo.", "p": ["INCR suma 1 de forma atómica.", "INCRBY suma una cantidad elegida.", "Si la clave no existe, INCR empieza en 0."], "c": "INCR visitas:home", "h": "Suma una visita.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que suma una cantidad elegida es ___ (6 letras)", "e": "Guardar contadores muy usados en una base SQL con UPDATE."},
  {"m": "Redis y otras bases en producción", "t": "Limitar peticiones con Redis", "x": "Contar las peticiones de cada usuario por ventana de tiempo.\n\nINCR intentos:ip:203.0.113.5 y EXPIRE de 60 s la primera vez. Si el valor pasa de 100, respondes 429. Como Redis es compartido, el límite funciona con varias copias del servidor.", "u": "Frenar abusos en una API repartida en varios servidores.\n\nTu API corre en 4 servidores y cada uno lleva su propio conteo de peticiones, así que el límite no funciona.", "p": ["Redis sirve para contar peticiones por ventana de tiempo.", "EXPIRE reinicia la ventana.", "Funciona aunque haya varias copias del servidor."], "c": "INCR intentos:ip:1\nEXPIRE intentos:ip:1 60", "h": "Cuenta un intento con ventana de 60 segundos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que define el tiempo de vida de una clave es ___ (6 letras)", "e": "Guardar el conteo en la memoria de cada servidor."},
  {"m": "Redis y otras bases en producción", "t": "Sesiones en Redis", "x": "Guardar las sesiones de usuario en Redis.\n\nLa cookie guarda solo el id; Redis guarda los datos con TTL (por ejemplo 7 días). connect-redis en Express o Flask-Session en Python lo configuran.", "u": "Que la sesión funcione en todas las copias del servidor y sea rápida.\n\nTu app tiene 3 servidores y al pasar de uno a otro el usuario pierde la sesión.", "p": ["Las sesiones en Redis sirven para varios servidores.", "La cookie guarda solo el id de la sesión.", "El TTL hace que las sesiones venzan solas."], "c": "SET sesion:abc '{\"usuario\":7}' EX 604800", "h": "Guarda una sesión por 7 días.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En Python, la extensión para sesiones en Redis es Flask-___ (7 letras)", "e": "Guardar sesiones en la memoria de cada servidor."},
  {"m": "Redis y otras bases en producción", "t": "Transacciones en Redis", "x": "Ejecutar varias órdenes juntas sin que otras se metan en medio.\n\nMULTI empieza, las órdenes quedan en cola y EXEC las ejecuta todas seguidas. WATCH clave cancela la transacción si alguien cambió esa clave antes de EXEC.", "u": "Mover datos entre claves de forma segura.\n\nDebes restar stock y agregar el producto al carrito sin que otra petición se meta en medio.", "p": ["MULTI y EXEC agrupan órdenes.", "Las órdenes se ejecutan seguidas sin interrupciones.", "WATCH cancela si la clave cambió."], "c": "MULTI\nDECR stock:7\nRPUSH carrito:3 7\nEXEC", "h": "Mueve un producto al carrito de forma segura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que empieza una transacción es ___ (5 letras)", "e": "Esperar que Redis deshaga los cambios si una orden falla dentro de EXEC."},
  {"m": "Redis y otras bases en producción", "t": "Persistencia: RDB y AOF", "x": "Formas en que Redis guarda los datos en disco.\n\nRDB toma fotos cada cierto tiempo (rápido, pero puede perder los últimos minutos). AOF registra cada escritura (más seguro). Se pueden usar los dos.", "u": "No perder datos si Redis se reinicia.\n\nRedis se reinició y perdiste los datos de los últimos 4 minutos.", "p": ["RDB guarda fotos periódicas de los datos.", "AOF registra cada escritura.", "Se pueden combinar RDB y AOF."], "c": "CONFIG SET appendonly yes", "h": "Activa el registro de escrituras.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El modo que registra cada escritura se abrevia ___ (3 letras)", "e": "Usar Redis como única copia de datos importantes sin persistencia."},
  {"m": "Redis y otras bases en producción", "t": "Alta disponibilidad en Redis", "x": "Sentinel y Cluster para que Redis siga funcionando si cae un servidor.\n\nSentinel vigila un Redis principal y sus réplicas, y elige un nuevo principal si cae. Redis Cluster además reparte los datos entre varios nodos con 16 384 slots.", "u": "Evitar que la caída de Redis tumbe tu app.\n\nTus datos de Redis ya no caben en un servidor y además necesitas que siga funcionando si uno cae.", "p": ["Sentinel elige un nuevo principal si el actual cae.", "Redis Cluster reparte los datos entre nodos.", "Cluster usa 16 384 slots."], "c": "CLUSTER INFO", "h": "Muestra el estado del clúster.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El vigilante que elige un nuevo principal se llama ___ (8 letras, en inglés)", "e": "Depender de un solo Redis sin réplica en producción."},
  {"m": "Redis y otras bases en producción", "t": "Patrones de caché", "x": "Formas de leer y escribir combinando caché y base de datos.\n\nCache-aside: la app busca en caché; si no está, lee la base y guarda en caché. Write-through: al escribir, actualiza base y caché a la vez. Write-behind: escribe en caché y luego en la base.", "u": "Elegir cómo mantener la caché al día.\n\nTu app primero busca en Redis y, si no encuentra, lee MySQL y guarda el resultado en Redis.", "p": ["En cache-aside la app llena la caché cuando falta el dato.", "Write-through actualiza base y caché a la vez.", "Write-behind escribe primero en la caché."], "c": "GET producto:7", "h": "Busca primero en la caché.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El patrón donde la app llena la caché al faltar el dato es cache-___ (5 letras, en inglés)", "e": "Usar write-behind con datos que no puedes perder."},
  {"m": "Redis y otras bases en producción", "t": "Invalidar la caché", "x": "Borrar o actualizar la caché cuando el dato original cambia.\n\nAl actualizar un producto en la base, borras su clave (DEL producto:7) para que la próxima lectura traiga el dato nuevo. El TTL es la red de seguridad si se olvida.", "u": "No mostrar precios o datos viejos.\n\nCambiaste el precio de un producto en la base, pero la tienda sigue mostrando el precio viejo.", "p": ["Invalidar es borrar la caché cuando cambia el dato.", "DEL borra una clave de Redis.", "El TTL limita cuánto puede durar un dato viejo."], "c": "DEL producto:7", "h": "Borra la caché del producto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que borra una clave de Redis es ___ (3 letras)", "e": "Guardar en caché sin TTL ni invalidación."},
  {"m": "Redis y otras bases en producción", "t": "Colas con listas de Redis", "x": "Usar listas de Redis como cola de trabajos sencilla.\n\nEl productor hace LPUSH trabajos '{...}' y el trabajador espera con BRPOP trabajos 0, que bloquea hasta que haya algo. Para reintentos y confirmaciones, mejor Streams o BullMQ.", "u": "Procesar tareas en segundo plano sin otro servicio.\n\nQuieres un trabajador que espere tareas nuevas sin consultar Redis cada segundo.", "p": ["LPUSH agrega un trabajo a la cola.", "BRPOP espera hasta que haya un trabajo.", "Para reintentos se prefieren Streams."], "c": "LPUSH trabajos '{\"correo\":\"ana@correo.com\"}'", "h": "Agrega un trabajo a la cola.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que espera bloqueada un trabajo es ___ (5 letras)", "e": "Consultar la cola en un bucle sin pausa."},
  {"m": "Redis y otras bases en producción", "t": "Bloqueos distribuidos", "x": "Asegurar que solo un servidor haga cierta tarea a la vez.\n\nSET bloqueo:cobro:42 <id> NX EX 30 solo funciona si la clave no existe (NX) y vence en 30 s. Al terminar se borra si el valor sigue siendo tu id.", "u": "Evitar que dos copias del servidor cobren dos veces o envíen dos correos.\n\nTus 3 servidores ejecutan la misma tarea nocturna y cobran 3 veces.", "p": ["NX solo crea la clave si no existe.", "EX hace que el bloqueo venza solo.", "Se borra al terminar si sigue siendo tuyo."], "c": "SET bloqueo:cobro:42 srv1 NX EX 30", "h": "Toma el bloqueo por 30 segundos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción de SET que solo crea si no existe es ___ (2 letras)", "e": "Tomar bloqueos sin vencimiento y dejarlos pegados si el servidor cae."},
  {"m": "Redis y otras bases en producción", "t": "Reglas de seguridad de Firestore", "x": "Reglas que deciden quién puede leer o escribir cada documento.\n\nmatch /usuarios/{uid} { allow read, write: if request.auth.uid == uid; } deja a cada usuario solo su documento. Sin reglas, cualquiera con tu configuración web puede leer todo.", "u": "Que nadie acceda a los datos de otros desde la app.\n\nTu app de Firebase deja que cualquier usuario lea los datos de los demás.", "p": ["Las reglas de Firestore deciden quién lee o escribe.", "request.auth.uid es el usuario que inició sesión.", "Sin reglas, cualquiera puede leer los datos."], "c": "allow read, write: if request.auth.uid == uid;", "h": "Permite a cada usuario solo su documento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El usuario que inició sesión en las reglas es request.auth.___ (3 letras)", "e": "Dejar las reglas en modo de prueba en producción."},
  {"m": "Redis y otras bases en producción", "t": "Firestore en tiempo real", "x": "Escuchar los cambios de documentos y consultas al instante.\n\nonSnapshot(query(collection(db, \"mensajes\"), orderBy(\"fecha\")), snap => ...) llama a la función con cada cambio. Funciona también sin conexión y sincroniza al volver.", "u": "Hacer chats o paneles que se actualizan solos.\n\nQuieres que los mensajes del chat aparezcan solos sin recargar.", "p": ["onSnapshot escucha cambios en tiempo real.", "La función se llama con cada cambio.", "Firestore sincroniza al recuperar la conexión."], "c": "onSnapshot(collection(db, \"mensajes\"), (snap) => console.log(snap.size))", "h": "Cuenta los mensajes en vivo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función de tiempo real de Firestore es on___ (8 letras, en inglés)", "e": "Olvidar cancelar el oyente y acumular lecturas que se cobran."},
  {"m": "Redis y otras bases en producción", "t": "Claves de partición", "x": "El campo que decide en qué servidor se guarda cada dato en bases distribuidas.\n\nEn Cassandra, PRIMARY KEY ((cliente), fecha) reparte por cliente y ordena por fecha dentro. Una clave con pocos valores (como el país) crea servidores sobrecargados.", "u": "Repartir bien los datos en Cassandra o DynamoDB.\n\nUsaste el país como clave de partición y el 90 % de los datos cayó en un solo servidor.", "p": ["La clave de partición decide en qué servidor va el dato.", "Una buena clave tiene muchos valores distintos.", "Dentro de la partición los datos se ordenan."], "c": "CREATE TABLE pedidos (cliente text, fecha timestamp, total int, PRIMARY KEY ((cliente), fecha));", "h": "Crea una tabla con clave de partición.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una partición con demasiados datos se llama partición ___ (7 letras, en inglés)", "e": "Elegir una clave con muy pocos valores distintos."},
  {"m": "Redis y otras bases en producción", "t": "Recomendaciones con grafos", "x": "Usar Neo4j para encontrar relaciones como «a quien le gustó esto también…».\n\nMATCH (yo:Usuario {id:1})-[:COMPRO]->(:Producto)<-[:COMPRO]-(otro)-[:COMPRO]->(rec) WHERE NOT (yo)-[:COMPRO]->(rec) RETURN rec, count(*) ORDER BY count(*) DESC encuentra recomendaciones.", "u": "Hacer recomendaciones y redes de amigos.\n\nQuieres recomendar productos que compraron personas con compras parecidas a las tuyas.", "p": ["Los grafos son ideales para recomendaciones.", "Cypher recorre relaciones con flechas.", "Se cuentan los caminos para ordenar recomendaciones."], "c": "MATCH (a:Usuario {id:1})-[:AMIGO]->(b) RETURN count(b)", "h": "Cuenta los amigos de un usuario.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El lenguaje de consultas de Neo4j es ___ (6 letras)", "e": "Hacer recomendaciones con muchos JOIN anidados en SQL."},
  {"m": "Redis y otras bases en producción", "t": "Elasticsearch para búsquedas", "x": "Motor de búsqueda con relevancia, tolerancia a errores y filtros.\n\nUn match con fuzziness: \"AUTO\" tolera errores, los analizadores entienden el español (stemming) y las agregaciones crean filtros por categoría y precio. Se usa junto a la base principal.", "u": "Hacer el buscador de una tienda o los logs de un sistema.\n\nTu tienda necesita un buscador con filtros por precio y que entienda «zapato» y «zapatos».", "p": ["Elasticsearch ordena los resultados por relevancia.", "fuzziness tolera errores de escritura.", "Se usa junto a la base de datos principal."], "c": "GET productos/_search { \"query\": { \"match\": { \"nombre\": { \"query\": \"zapato\", \"fuzziness\": \"AUTO\" } } } }", "h": "Busca tolerando errores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La opción de Elasticsearch para tolerar errores es ___ (9 letras, en inglés)", "e": "Usar Elasticsearch como única base de datos de pedidos."},
  {"m": "Redis y otras bases en producción", "t": "Respaldos de bases NoSQL", "x": "Copias de seguridad automáticas y probadas.\n\nAtlas tiene respaldos continuos con restauración a un momento exacto; en servidores propios usa mongodump o snapshots del disco. Redis: copia el archivo RDB/AOF. Prueba restaurar cada cierto tiempo.", "u": "Recuperar los datos ante borrados o fallos.\n\nUn compañero borró una colección por error a las 3:15 p. m.", "p": ["Los respaldos deben ser automáticos.", "Hay que probar que se pueden restaurar.", "Atlas permite restaurar a un momento exacto."], "c": "mongodump --uri \"$MONGO_URL\" --out respaldo-$(date +%F)", "h": "Hace un respaldo con la fecha.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La restauración a un momento exacto se llama point-in-___ (4 letras, en inglés)", "e": "Tener respaldos que nunca se han probado restaurar."},
  {"m": "Redis y otras bases en producción", "t": "Proyecto final NoSQL", "x": "Una app que combina MongoDB, Redis y buenas prácticas de diseño.\n\nAPI de una tienda: MongoDB con esquema validado, índices ESR, agregaciones para reportes y TTL para códigos; Redis para caché, sesiones y límite de peticiones; respaldos y usuarios con rol mínimo.", "u": "Demostrar que sabes elegir y usar bases NoSQL.\n\nQuieres mostrar en una entrevista que sabes NoSQL de verdad.", "p": ["Un buen proyecto combina la base adecuada para cada uso.", "Los índices se diseñan según las consultas.", "La seguridad y los respaldos son parte del proyecto."], "c": "db.productos.getIndexes().length", "h": "Cuenta los índices del proyecto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para caché y sesiones se usa ___ (5 letras)", "e": "Usar una sola base para todo sin pensar en cada caso."},
  {"m": "Redis y otras bases en producción", "t": "Ubicaciones con Redis", "x": "Guardar coordenadas y buscar lo que está cerca.\n\nGEOADD tiendas -74.07 4.71 centro guarda la ubicación y GEOSEARCH tiendas FROMLONLAT -74.06 4.70 BYRADIUS 3 km ASC devuelve las tiendas a menos de 3 km ordenadas por distancia.", "u": "Mostrar tiendas, domiciliarios o amigos cercanos.\n\nTu app de domicilios debe mostrar los restaurantes a menos de 3 km del usuario.", "p": ["GEOADD guarda la longitud y la latitud de un lugar.", "GEOSEARCH busca lugares dentro de un radio.", "Los resultados pueden ordenarse por distancia."], "c": "GEOADD tiendas -74.07 4.71 centro", "h": "Guarda la ubicación de una tienda.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La orden que guarda una ubicación es ___ (6 letras)", "e": "Calcular distancias a todos los lugares en el código."}
];
